    "completed_code": "def pseudo_quantize_tensor(w, n_bit=4, q_group_size=-1):\n    org_w_shape = w.shape\n    # 그룹 단위 양자화 적용 시 weight 행렬을 그룹 크기로 재구성\n    if q_group_size > 0:\n        assert org_w_shape[-1] % q_group_size == 0\n        w = w.reshape(-1, q_group_size)\n\n    assert w.dim() == 2\n\n    # 각 행(또는 그룹)별 최대값(α)과 최소값(β) 계산\n    max_val = w.amax(dim=1, keepdim=True)\n    min_val = w.amin(dim=1, keepdim=True)\n\n    # 스케일(scale)과 제로포인트(zero point) 계산\n    # scale = (α - β) / (2^n_bit - 1)\n    # zero = round(-β / scale)\n    max_int = 2 ** n_bit - 1\n    scales = (max_val - min_val).clamp(min=1e-5) / max_int\n    zeros = (-torch.round(min_val / scales)).clamp_(0, max_int)\n\n    # NaN 검증\n    assert torch.isnan(scales).sum() == 0\n    assert torch.isnan(w).sum() == 0\n\n    # 양자화(Quantization) 단계: 실수값을 정수 범위 [0, 2^n_bit - 1]로 매핑\n    w = torch.clamp(torch.round(w / scales) + zeros, 0, max_int)\n\n    # 복원 단계(Dequantization): 정수값을 다시 실수 범위로 변환 (pseudo quantization)\n    w = (w - zeros) * scales\n\n    # NaN 검증\n    assert torch.isnan(w).sum() == 0\n\n    # 원래 텐서 형태로 복원\n    w = w.reshape(org_w_shape)\n    return w",
